 const [session,setSession]=useState<any>(null),[company,setCompany]=useState<any>(null),[companyName,setCompanyName]=useState('My Factory'),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[authMsg,setAuthMsg]=useState(''),[busy,setBusy]=useState(false),[syncMsg,setSyncMsg]=useState('');
 const [form,setForm]=useState<any>({title:'',status:'Open',record_date:new Date().toISOString().slice(0,10),value:0,notes:'',details:{}});
