    const refs=[['Part number',p.details?.['Part number']],['BOM',p.details?.BOM],['BOM reference',p.details?.['BOM reference']],['BOM Ref',p.details?.['BOM Ref']],['Root BOM ID',p.details?.rootBOMId],['Sales item ID',p.details?.salesitemid],['Item ID',p.details?.itemid],['Reference',p.details?.Reference]].map(([field,value]:any)=>({field,value:String(value??'').trim(),key:normalizeRef(value)})).filter(x=>x.key);
